      'operations.cards.closingProcedures.tag3': 'Standard',
      'operations.cards.closingProcedures.title': 'Procedura di chiusura',
      'operations.cards.closingProcedures.desc': 'Tutte le fasi di chiusura per lasciare il negozio pronto per il giorno dopo.',
      'operations.cards.closingProcedures.stats': `<li>Pulisci tutte le superfici e attrezzi di lavoro</li><li>Spegni vetrina gelato (OFF ogni notte)</li><li>Registra temperature finali su log HACCP</li><li>Etichetta e copri tutti i prodotti in frigo</li><li>Controlla scadenze e FIFO per il giorno successivo</li>`,
      'operations.cards.closingProcedures.details': `<div class="steps"><span>1 · Pulisci superfici, macchina cappuccino, attrezzi.</span><span>2 · Spegni vetrina gelato e chiudi sliding doors.</span><span>3 · Registra temperature finali (HACCP).</span><span>4 · Copri e etichetta tutti i prodotti in frigo/freezer.</span><span>5 · Controlla FIFO e elimina prodotti scaduti.</span><span>6 · Svuota cestini, pulisci pavimenti.</span><span>7 · Chiudi cassa e compila report giornaliero.</span></div><div class="tips"><strong style="color: var(--brand-rose);">🛠️ Pro tip:</strong> Una chiusura fatta bene = un'apertura veloce domani.</div>`,

      'operations.cards.cleaningSchedule.tag1': 'Pulizia',
      'operations.cards.cleaningSchedule.tag2': 'Defrost',
      'operations.cards.cleaningSchedule.tag3': 'Weekly',
      'operations.cards.cleaningSchedule.title': 'Pulizia & Defrost',
      'operations.cards.cleaningSchedule.desc': 'Pulizia vetrina, deep clean filtri e sbrinamento freezer programmati per performance costanti.',
      'operations.cards.cleaningSchedule.stats': `<li>Vetrina gelato: pulisci vetri ogni giorno, deep clean settimanale</li><li>Filtri: deep cleaning settimanale (rimuovi, lava, asciuga, rimonta)</li><li>Treat freezer: defrost settimanale (sempre senza ghiaccio)</li><li>Vertical display: defrost settimanale (verifica -16 °C)</li>`,
      'operations.cards.cleaningSchedule.details': `<div class="steps"><strong>🧊 Pulizia vetrina gelato</strong><span>1 · Spegni vetrina a fine turno (OFF ogni notte).</span><span>2 · Pulisci vetri interni ed esterni con prodotto specifico.</span><span>3 · Deep clean settimanale: smonta, pulisci, sanitizza, lucida e rimonta.</span></div><hr style="margin: 12px 0; border: none; border-top: 1px dashed rgba(33, 64, 152, 0.2);"><div class="steps"><strong>🔧 Deep cleaning filtri</strong><span>1 · Rimuovi filtri dalla vetrina/freezer.</span><span>2 · Lava con acqua calda e detergente specifico.</span><span>3 · Asciuga completamente prima di rimontare.</span></div><hr style="margin: 12px 0; border: none; border-top: 1px dashed rgba(33, 64, 152, 0.2);"><div class="steps"><strong>❄️ Defrosting freezer</strong><span>1 · Treat freezer: defrost settimanale (deve risultare senza ghiaccio).</span><span>2 · Vertical display: defrost settimanale (verifica -16 °C dopo riavvio).</span><span>3 · Dopo ogni defrost: pulisci, asciuga e riaccendi.</span></div>`,








      'gelatoLab.cards.yoyo.title': 'Yo-Yo',
      'gelatoLab.cards.yoyo.desc': 'Biscotto morbido farcito con gelato: snack “grab & go” da servire subito.',
      'gelatoLab.cards.yoyo.stats': `<li>Conservazione wafer: temperatura ambiente</li><li>Servizio: Tovagliolino o piattino</li><li>Varianti: Classico, Pistacchio, Cioccolato</li>`,
      'gelatoLab.cards.yoyo.details': `<div class="steps"><strong data-i18n="modal.tab.preparation"></strong><span>1 · Preleva i wafer dal display.</span><span>2 · Servi immediatamente per evitare che il gelato si sciolga.</span><span>3 · Suggerisci come snack veloce o dessert da passeggio.</span></div>`,

      'gelatoLab.ops.yoyoSetup.title': 'Allestimento Yo-Yo (banco)',
      'gelatoLab.ops.yoyoSetup.desc': 'Yo‑Yo al centro sopra la vetrina: area sempre pulita e rifornita (mai vuoto visivo).',
      'gelatoLab.ops.yoyoSetup.stats': `<li>Posizionamento: centrale, sopra la gelato vetrina</li><li>Hygiene: superficie sempre free of crumbles</li><li>Replenish: riempi/rifornisci ogni volta (mai “vuoto” visivo)</li>`,
      'gelatoLab.ops.yoyoSetup.details': `<div class="steps"><strong data-i18n="modal.tab.preparation"></strong><span>1 · Pulisci l'area (zero briciole).</span><span>2 · Posiziona la stazione Yo-Yo in punto visibile e centrale.</span><span>3 · Prepara wafer/tool e guanti monouso per il servizio.</span></div><div class="tips"><strong data-i18n="modal.tab.tips"></strong>Il Yo-Yo vende anche “con gli occhi”: non lasciarlo mai disordinato.</div>`,

      'gelatoLab.ops.yoyoTools.title': 'Stazione e strumenti (standard)',
      'gelatoLab.ops.yoyoTools.desc': 'Stazione pronta = servizio veloce e pulito: guanti, tool e wafer già a portata.',
      'gelatoLab.ops.yoyoTools.stats': `<li>Guanti: indossali prima di maneggiare wafer/Yo-Yo tool</li><li>Tool: appoggia Yo-Yo tool su un piatto con 2 wafer pronti</li><li>Flow: prepara wafer → gelato → chiusura, senza “giri” inutili</li>`,
      'gelatoLab.ops.yoyoTools.details': `<div class="steps"><strong data-i18n="modal.tab.preparation"></strong><span>1 · Guanti on.</span><span>2 · Wafer sul tool, una base pronta.</span><span>3 · Chiudi subito dopo porzionatura per evitare overflow.</span></div><div class="tips"><strong data-i18n="modal.tab.tips"></strong>Ordine fisso = velocità e costanza tra team.</div>`,

      'gelatoLab.ops.yoyoPortioning.title': 'Porzionatura gelato Yo-Yo',
