      'quiz.q.tm-029.option.3': 'Tape before the lid',
      'quiz.q.tm-029.explain': 'Standard: fill by pressing, without air pockets.',

      'quiz.q.tm-030.question': 'Gelato box: which closing action is correct?',
      'quiz.q.tm-030.option.0': 'Seal with Badiani tape on the box-lid contact',
